// PocketBasePlus Documents module (optional, see internal/documents): PDF
// templates built from blocks, generated by the flows.
//
// PocketBase concatenates every extension's main.js into /_/extensions.js, so
// this one is wrapped in a block to keep its names to itself.
{
    globalThis.gpInternalCollections = [...(globalThis.gpInternalCollections || []), "document_templates", "documents"];
    // the flow editor offers the "Generate document" step
    globalThis.gpDocuments = true;

    const docsBase = app.pb.buildURL("/_/extensions/pocketbaseplus-documents/");
    const loadDocs = (file) => import(docsBase + file);

    const links = app.store?.headerLinks;
    if (Array.isArray(links)) {
        const after = links.findIndex((l) => l.href == "#/forms");
        links.splice(after >= 0 ? after + 1 : links.length, 0, { href: "#/documents", icon: "ri-file-pdf-2-line", label: "Documents" });
    } else {
        console.warn("[pocketbaseplus-documents] app.store.headerLinks not found, check internal/documents/ext/main.js after the PocketBase upgrade");
    }

    app.routes.superuserOnly("#/documents", async (route) => (await loadDocs("documents.js")).pageDocuments(route));
    // before #/documents/{id}
    app.routes.superuserOnly("#/documents/generated", async (route) => (await loadDocs("documents.js")).pageGenerated(route));
    app.routes.superuserOnly("#/documents/{id}", async (route) => (await loadDocs("editor.js")).pageEditor(route));
}
